import org.HdrHistogram.Recorder;
import java.net.http.*;
import java.util.concurrent.*;

public class OpenLoopLoadDriver {
    private static final long INTERVAL_NS = 200_000L; // 5,000 RPS
    private static final int MAX_IN_FLIGHT = 2048;
    private final Semaphore inFlight = new Semaphore(MAX_IN_FLIGHT);
    private final ConcurrentLinkedQueue<Long> pendingTicks = new ConcurrentLinkedQueue<>();
    private final Recorder responseRecorder = new Recorder(1_000L, 60_000_000_000L, 3);
    private final HttpClient client = HttpClient.newBuilder()
            .version(HttpClient.Version.HTTP_2)
            .build();

    public void runPacer(long durationNs, HttpRequest req) {
        long endNs = System.nanoTime() + durationNs;
        long nextTickNs = System.nanoTime();
        while (nextTickNs < endNs) {
            long now = System.nanoTime();
            if (now >= nextTickNs) {
                pendingTicks.offer(nextTickNs);
                tryDispatch(req);
                nextTickNs += INTERVAL_NS;
            } else {
                Thread.onSpinWait();
            }
        }
    }

    private void tryDispatch(HttpRequest req) {
        if (!inFlight.tryAcquire()) return; // queue retains intendedStartNs!
        Long intendedNs = pendingTicks.poll();
        if (intendedNs == null) { inFlight.release(); return; }
        client.sendAsync(req, HttpResponse.BodyHandlers.discarding())
              .whenComplete((res, err) -> {
                  long latencyNs = System.nanoTime() - intendedNs;
                  responseRecorder.recordValueWithExpectedInterval(latencyNs, INTERVAL_NS);
                  inFlight.release();
                  if (!pendingTicks.isEmpty()) tryDispatch(req);
              });
    }
}

// Safe queue cap prevents OOM during total server outage
if (pendingTicksSize.get() < 100_000) {
    pendingTicks.offer(nextTickNs);
    pendingTicksSize.incrementAndGet();
} else {
    responseRecorder.recordValue(30_000_000_000L); // 30s timeout floor
}

// Merging distributed HdrHistograms accurately
Histogram global = new Histogram(1_000L, 60_000_000_000L, 3);
for (Histogram workerHist : workerHistograms) {
    global.add(workerHist);
}
System.out.printf("Global p99.9: %.2f ms%n", global.getValueAtPercentile(99.9) / 1e6);

// Poisson inter-arrival generator (exponential distribution)
long nextPoissonIntervalNs(ThreadLocalRandom rng, double meanIntervalNs) {
    double u = Math.max(1e-12, rng.nextDouble());
    return (long) (-Math.log(u) * meanIntervalNs);
}
